	i = s[j]
	curword = l[cur]
	if stage == 0 and i == '<':
		stage = 1
	elif stage == 1 and i == '3':
		stage = 2
	if stage == 2:
		if i == curword[curpos]:
			curpos += 1
		if curpos == len(curword):
			cur += 1
			curpos = 0
			stage = 0
			if cur == len(l):
				for k in range(j + 1, len(s)):
					if s[k] == '<' and f == 0:
						f = 1
					if s[k] == '3' and f == 1:
						f = 2
				break
if cur == len(l) and f == 2:
	print('yes')
